// src/app/rechner/pacht/page.js – Pachtrechner Solarpark

import Link from "next/link";
import RechnerSeite, { rechnerMetadata } from "@/components/Rechner/RechnerSeite";
import PachtRechner from "@/components/Flaeche/PachtRechner";
import SectionHeading from "@/components/ui/SectionHeading";
import Reveal from "@/components/ui/Reveal";
import { JahresSaeulen } from "@/components/Flaeche/Verpachten/Pachtmodelle";
import { pachtRechnung } from "@/lib/rechner/pacht";
import { ERLOESE, FREIFLAECHE, PACHT } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";

const PFAD = "/rechner/pacht";

export const metadata = rechnerMetadata({
  pfad: PFAD,
  title: "Pachtrechner Solarpark: Pacht über 30 Jahre | ÖkoInvest",
  description:
    "Solarpark-Pacht berechnen: Festpacht, indexiert oder Umsatzbeteiligung über 30 Jahre – im Vergleich zu Ackerpacht und Deckungsbeitrag. Kostenlos.",
  keywords: ["Pachtrechner Solarpark", "Solarpark Pacht berechnen", "Umsatzpacht Solarpark", "Pacht indexiert Photovoltaik", "Freiflächen PV Pacht"],
});

const FAQ = [
  {
    q: "Wie viel Pacht pro Hektar zahlt ein Solarpark?",
    a: `Im DACH-Raum liegen Solarpachten derzeit meist zwischen ${fmt(PACHT.freiflaecheProHa.min)} und ${fmt(PACHT.freiflaecheProHa.max)} € je Hektar und Jahr. Hohe Werte gibt es für große Flächen mit nahem Netzanschluss in der EEG-Kulisse, niedrigere bei langen Kabeltrassen, kleinen Flächen oder schwierigem Baurecht.`,
  },
  {
    q: "Was ist besser: Festpacht oder Umsatzbeteiligung?",
    a: `Festpacht ist planbar und unabhängig vom Strompreis. Eine Umsatzbeteiligung von ${fmt(PACHT.umsatzbeteiligung.min * 100)}–${fmt(PACHT.umsatzbeteiligung.max * 100)} % lässt Sie an steigenden Strompreisen teilhaben, schwankt aber mit Ertrag und Preis. Viele Eigentümer wählen eine Kombination: Umsatzbeteiligung mit Mindestpacht – oder eine indexierte Festpacht.`,
  },
  {
    q: "Warum ist die Solarpacht so viel höher als die Ackerpacht?",
    a: `Weil auf einem Hektar rund ${fmt(1 / FREIFLAECHE.haProMwp, 1)} MWp Leistung stehen, die jährlich Strom für mehrere zehntausend Euro erzeugen. Die Pacht ist nur ein kleiner Teil davon. Dafür ist die Fläche 30 Jahre gebunden – die Rückgabe ist über Vertrag, Grundbuch und Rückbaubürgschaft gesichert.`,
  },
  {
    q: "Ist die Pacht vor Baubeginn schon fällig?",
    a: `Nein, die volle Pacht beginnt in der Regel mit dem Bau oder der Inbetriebnahme. Bis dahin zahlen wir meist eine Reservierungsprämie von ${fmt(PACHT.reservierungProHa.min)}–${fmt(PACHT.reservierungProHa.max)} € je Hektar und Jahr, und Sie bewirtschaften weiter. Das können Sie im Rechner über „Vorlauf bis Baubeginn“ abbilden.`,
  },
  {
    q: "Wie wird die Pacht versteuert?",
    a: "Pachteinnahmen sind einkommensteuerpflichtig. Zudem kann die Verpachtung für einen Solarpark Grund- und Erbschaftsteuer beeinflussen. Der Rechner zeigt Werte vor Steuern – lassen Sie Ihren Fall vor Vertragsschluss von Ihrer Steuerberatung prüfen.",
  },
];

/** Mini-Vergleich der drei Modelle (Beispiel 10 ha, Süd-DE, Standardwerte des Rechners) */
function ModellMinis() {
  const reihen = [
    { t: "Festpacht", x: "gleichbleibend", r: pachtRechnung({ modell: "fest" }), ton: "fill-ov-400" },
    { t: "Indexiert", x: `+${fmt(PACHT.indexierung * 100, 1)} % p. a.`, r: pachtRechnung({ modell: "index" }), ton: "fill-ov-600" },
    { t: "Umsatz", x: "6 % der Erlöse", r: pachtRechnung({ modell: "umsatz", umsatzAnteil: 0.06 }), ton: "fill-navy-500" },
  ];
  const max = Math.max(...reihen.flatMap((m) => m.r.jahre.map((j) => j.solar)));
  return (
    <Reveal className="mt-8 grid max-w-2xl gap-3 sm:grid-cols-3">
      {reihen.map((m) => (
        <div key={m.t} className="rounded-2xl bg-sand-50 p-4 ring-1 ring-ink-200/60">
          <p className="font-display text-[15.5px] font-bold text-ink-900">{m.t}</p>
          <p className="text-[12.5px] text-ink-600">{m.x}</p>
          <div className="mt-3 rounded-xl bg-white px-2.5 pb-1.5 pt-2.5 ring-1 ring-ink-200/70">
            <JahresSaeulen jahre={m.r.jahre} max={max} ton={m.ton} />
          </div>
          <p className="mt-2 flex items-baseline justify-between text-[12.5px] text-ink-600">
            <span>Jahr 1–{PACHT.laufzeit}</span>
            <span className="ov-num font-bold text-ink-900">{fmt(Math.round(m.r.summeSolar / 1000))} Tsd. €</span>
          </p>
        </div>
      ))}
      <p className="text-[12.5px] leading-relaxed text-ink-500 sm:col-span-3">Beispiel 10 ha in Süddeutschland mit den Standardwerten des Rechners; jede Säule ist ein Jahr. Nominal, vor Steuern.</p>
    </Reveal>
  );
}

export default function Page() {
  return (
    <RechnerSeite
      pfad={PFAD}
      toolId="pacht"
      breadcrumb="Pachtrechner"
      eyebrow="Pachtrechner Solarpark"
      title={<>Was bringt Ihre Fläche <span className="ov-text-gradient-light">in 30 Jahren?</span></>}
      lead="Festpacht, indexiert oder Umsatzbeteiligung – Ihre Pacht über die gesamte Laufzeit, im direkten Vergleich zu Ackerpacht und eigenem Ackerbau."
      chips={["Kostenlos & ohne Anmeldung", "Drei Pachtmodelle", "Vergleich mit Ackerbau"]}
      app={{
        name: "ÖkoInvest Pachtrechner Solarpark",
        description: "Berechnet die Pacht für Freiflächen-Photovoltaik je Hektar über die Laufzeit – Festpacht, indexiert oder Umsatzbeteiligung – im Vergleich zu Ackerpacht und Deckungsbeitrag.",
        featureList: ["Festpacht, Indexierung, Umsatzbeteiligung", "Mindestpacht", "Reservierungsprämie bis Baubeginn", "Vergleich Ackerpacht und Deckungsbeitrag", "Kumulierte Einnahmen über 20–40 Jahre"],
      }}
      rechner={<PachtRechner />}
      erklaerung={
        <>
          <SectionHeading
            eyebrow="So rechnen wir"
            title="Die Pacht ist planbar – der Vergleich zeigt, was sie wert ist."
            lead="Ein Solarpark bindet die Fläche für Jahrzehnte. Deshalb vergleichen wir nicht nur mit der Ackerpacht, sondern auch mit dem, was Sie selbst als Deckungsbeitrag erwirtschaften würden."
          />
          <ModellMinis />
          <div className="ov-prose mt-8 max-w-2xl">
            <p>
              Bei der <strong>Festpacht</strong> bleibt der Betrag über die Laufzeit gleich, bei der <strong>indexierten Pacht</strong> steigt er mit {fmt(PACHT.indexierung * 100, 1)} % pro Jahr. Die <strong>Umsatzbeteiligung</strong> rechnen wir auf den erwarteten Stromertrag Ihrer Region – die ersten 20 Jahre mit dem durchschnittlichen EEG-Zuschlagswert von {fmt(ERLOESE.eegFreiflaecheCt, 1)} ct/kWh, danach vorsichtig mit {fmt(ERLOESE.merchantCt, 1)} ct/kWh Marktwert.
            </p>
            <p>
              Ackerpacht und Deckungsbeitrag schreiben wir mit derselben Rate fort, damit der Vergleich fair bleibt. Was Ihre konkrete Fläche hergibt, zeigt der <Link href="/flaechencheck">Flächencheck</Link>; was im Pachtvertrag steht, lesen Sie unter <Link href="/flaeche-verpachten">Fläche verpachten</Link>.
            </p>
          </div>
        </>
      }
      annahmen={[
        ["Pacht Freifläche (Spanne)", `${fmt(PACHT.freiflaecheProHa.min)}–${fmt(PACHT.freiflaecheProHa.max)} €/ha·a`],
        ["Umsatzbeteiligung üblich", `${fmt(PACHT.umsatzbeteiligung.min * 100)}–${fmt(PACHT.umsatzbeteiligung.max * 100)} %`],
        ["Indexierung", `${fmt(PACHT.indexierung * 100, 1)} % p. a.`],
        ["Flächenbedarf", `${fmt(FREIFLAECHE.haProMwp, 1)} ha je MWp`],
        ["Strompreis Jahr 1–20 / danach", `${fmt(ERLOESE.eegFreiflaecheCt, 1)} / ${fmt(ERLOESE.merchantCt, 1)} ct/kWh`],
        ["Degradation", `${fmt(FREIFLAECHE.degradation * 100, 1)} % p. a.`],
        ["Ackerpacht Ø Deutschland", `${fmt(PACHT.ackerProHa)} €/ha·a`],
        ["Reservierungsprämie", `${fmt(PACHT.reservierungProHa.min)}–${fmt(PACHT.reservierungProHa.max)} €/ha·a`],
      ]}
      quellen={[
        { name: "Bundesnetzagentur – Ausschreibungen Solar", url: "https://www.bundesnetzagentur.de/DE/Fachthemen/ElektrizitaetundGas/Ausschreibungen/Solaranlagen1/start.html" },
        { name: "Destatis – Landwirtschaft", url: "https://www.destatis.de/DE/Themen/Branchen-Unternehmen/Landwirtschaft-Forstwirtschaft-Fischerei/_inhalt.html" },
        { name: "PVGIS", url: "https://re.jrc.ec.europa.eu/pvg_tools/de/" },
      ]}
      faq={FAQ}
      querverweise={[
        { href: "/flaeche-verpachten", titel: "Fläche verpachten", text: "Pachtvertrag, Rückbausicherheit, Steuern und der Weg bis zur ersten Zahlung." },
        { href: "/flaechencheck", titel: "Flächencheck", text: "Eignung, Leistung und Pachtspanne Ihrer konkreten Fläche." },
        { href: "/rechner/agri-pv", titel: "Agri-PV-Rechner", text: "Wenn Sie weiter bewirtschaften möchten: Pacht, Eigeninvestition oder Beteiligung." },
      ]}
      cta={{
        eyebrow: "Für Flächeneigentümer kostenfrei",
        title: "Aus der Rechnung ein echtes Pachtangebot machen?",
        text: "Wir prüfen Ihre Fläche am Kartentisch und legen Ihnen ein schriftliches Angebot mit Vertragsentwurf vor – ohne Kosten und ohne Verpflichtung.",
        primary: { label: "Fläche prüfen lassen", href: "/flaechencheck" },
        secondary: { label: "Fläche verpachten", href: "/flaeche-verpachten" },
      }}
    />
  );
}
// src/app/angebot/page.js – Eingabe des persönlichen Codes aus dem Anschreiben (noindex).
import { CodeEingabe } from "@/components/Angebot/AngebotAktionen";
import { Briefbild, STECKBRIEF_INHALT, ZUSAGEN } from "@/components/Angebot/Buehne";
import Stagger from "@/components/ui/Stagger";
import { TextEnthuellung } from "@/components/motion";

export const metadata = {
  title: "Persönlicher Code | ÖkoInvest",
  description: "Geben Sie den persönlichen Code aus unserem Anschreiben ein, um den Steckbrief Ihrer Fläche mit unverbindlicher Pachtspanne und Pachtrechner zu öffnen.",
  robots: { index: false, follow: false },
  referrer: "no-referrer",
};

export default function AngebotCode() {
  return (
    <>
      <section aria-labelledby="code-titel" className="ov-verlauf-nacht ov-noise relative isolate overflow-hidden text-white">
        <div aria-hidden="true" className="ov-grid-bg absolute inset-0 -z-10 opacity-50" />
        <div aria-hidden="true" className="pointer-events-none absolute inset-x-0 top-0 -z-10 h-px bg-gradient-to-r from-transparent via-ov-300/40 to-transparent" />
        <div aria-hidden="true" className="pointer-events-none absolute -left-40 -top-40 -z-10 h-[520px] w-[520px] rounded-full bg-ov-500/20 blur-[120px]" />
        <div className="ov-container grid grid-cols-[minmax(0,1fr)] items-center gap-y-16 py-16 md:py-24 lg:grid-cols-[minmax(0,1fr)_minmax(0,0.9fr)] lg:gap-x-16">
          <div className="max-w-[36rem]">
            <p className="ov-hero-in inline-flex items-center gap-2.5 rounded-full bg-white/[0.06] py-1 pl-1 pr-3.5 text-[13px] text-white/85 ring-1 ring-inset ring-white/15" style={{ "--ov-delay": "40ms" }}>
              <span className="rounded-full bg-ov-300 px-2 py-0.5 text-[11px] font-bold uppercase tracking-[0.08em] text-navy-950">Ihr Anschreiben</span>
              Flächen-Steckbrief öffnen
            </p>
            <h1 id="code-titel" className="ov-h1 mt-6 text-balance md:mt-8">
              <TextEnthuellung verzoegerung={80}>
                Persönlichen Code <span className="ov-text-gradient-light">eingeben</span>
              </TextEnthuellung>
            </h1>
            <p className="ov-lead ov-hero-in mt-5 text-pretty text-white/75" style={{ "--ov-delay": "180ms" }}>
              Den Code finden Sie in unserem Schreiben rechts oben (zehn Zeichen, z. B. ABCDE-23456). Alternativ scannen Sie den QR-Code im Brief.
            </p>

            <div className="ov-hero-in relative mt-8 md:mt-10" style={{ "--ov-delay": "260ms" }}>
              <div aria-hidden="true" className="absolute -inset-4 rounded-[2.25rem] bg-ov-500/20 blur-2xl" />
              <div className="relative rounded-[1.75rem] bg-white p-5 text-ink-900 shadow-e5 ring-1 ring-white/20 sm:p-6">
                <p className="mb-3 text-[13.5px] font-semibold text-ink-800">Ihr persönlicher Code</p>
                <CodeEingabe />
              </div>
            </div>

            <ul className="ov-hero-in mt-8 grid gap-3 sm:grid-cols-3" style={{ "--ov-delay": "320ms" }}>
              {ZUSAGEN.map((z) => (
                <li key={z.t} className="flex gap-3 sm:block">
                  <z.icon aria-hidden="true" className="mt-0.5 h-5 w-5 shrink-0 text-ov-300" />
                  <span className="min-w-0 sm:mt-2 sm:block">
                    <span className="block text-[14px] font-semibold leading-snug text-white">{z.t}</span>
                    <span className="mt-0.5 block text-[13px] leading-snug text-white/65">{z.x}</span>
                  </span>
                </li>
              ))}
            </ul>
          </div>

          <div className="ov-hero-in mx-auto w-full max-w-[460px] px-4 pb-8 pt-10 sm:px-8 lg:mr-0" style={{ "--ov-delay": "200ms" }}>
            <Briefbild />
          </div>
        </div>
      </section>

      <section aria-labelledby="inhalt-titel" className="bg-sand-50 py-16 md:py-24">
        <div className="ov-container">
          <div className="grid gap-10 lg:grid-cols-[minmax(0,0.8fr)_minmax(0,1.2fr)] lg:gap-16">
            <div>
              <p className="inline-flex items-center gap-2 text-[12.5px] font-semibold uppercase tracking-[0.16em] text-ov-700">
                <span aria-hidden="true" className="h-1.5 w-1.5 rounded-full bg-ov-500" />
                Ihr Steckbrief
              </p>
              <h2 id="inhalt-titel" className="ov-h2 mt-4 text-ink-900">Was Sie nach der Eingabe sehen</h2>
              <p className="ov-lead mt-5 text-ink-600">Eine erste, unverbindliche Einschätzung Ihrer Fläche – und die Möglichkeit, die Pacht selbst durchzurechnen. Kontakt nehmen nur Sie auf, wenn Sie möchten.</p>
            </div>
            <Stagger as="ul" schritt={90} className="grid gap-3 sm:grid-cols-2">
              {STECKBRIEF_INHALT.map((s, i) => (
                <li key={s.t} className="rounded-3xl bg-white p-5 ring-1 ring-ink-200/70 md:p-6">
                  <div className="flex items-center justify-between">
                    <span aria-hidden="true" className="flex h-11 w-11 items-center justify-center rounded-2xl bg-ov-50 text-ov-600 ring-1 ring-ov-200">
                      <s.icon className="h-5 w-5" />
                    </span>
                    <span aria-hidden="true" className="ov-num font-display text-[28px] font-extrabold leading-none text-ink-100">{String(i + 1).padStart(2, "0")}</span>
                  </div>
                  <h3 className="mt-4 font-display text-[17px] font-bold text-ink-900">{s.t}</h3>
                  <p className="mt-1.5 text-[14.5px] leading-relaxed text-ink-600">{s.x}</p>
                </li>
              ))}
            </Stagger>
          </div>
        </div>
      </section>
    </>
  );
}

// src/app/flaechencheck/page.js – Flächencheck (Wizard)

import Section from "@/components/ui/Section";
import SectionHeading from "@/components/ui/SectionHeading";
import Reveal from "@/components/ui/Reveal";
import Faq from "@/components/ui/Faq";
import CtaBand from "@/components/ui/CtaBand";
import Querverweise from "@/components/Reusable/Querverweise";
import FlaechenWizard from "@/components/Flaeche/FlaechenWizard";
import { CheckHero, SoBewertenWir } from "@/components/Flaeche/Check/Abschnitte";
import { AnnahmenBox } from "@/components/Rechner/RechnerSeite";
import { abs } from "@/data/site";
import { FREIFLAECHE, PACHT, PROVISION } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";

const PFAD = "/flaechencheck";
const TITEL = "Flächencheck Solarpark: Eignet sich Ihre Fläche? | ÖkoInvest";
const BESCHREIBUNG =
  "Eignet sich Ihre Fläche für Solarpark oder Agri-PV? Lage, Größe, Nutzung und Netz angeben – Ampel, Leistung, Stromertrag und Pachtspanne in zwei Minuten.";

export const metadata = {
  title: TITEL,
  description: BESCHREIBUNG,
  alternates: { canonical: abs(PFAD) },
  robots: { index: true, follow: true },
  openGraph: {
    type: "website",
    locale: "de_DE",
    url: abs(PFAD),
    siteName: "ÖkoInvest",
    title: TITEL,
    description: BESCHREIBUNG,
    images: [{ url: abs("/img/freiflaeche-begehung.jpg"), width: 1280, height: 852, alt: "Begehung einer Fläche für einen Solarpark" }],
  },
};

const FAQ = [
  {
    q: "Wie genau ist der Flächencheck?",
    a: "Er ist eine erste, transparente Einschätzung auf Basis Ihrer Angaben und typischer Marktwerte – vergleichbar mit dem ersten Gespräch mit einem Projektentwickler. Netzkapazität, Planungsrecht, Schutzgebiete und Bodenverhältnisse prüfen wir anschließend flurstückgenau.",
  },
  {
    q: "Was passiert mit meinen Angaben?",
    a: "Solange Sie das Formular nicht absenden, bleiben alle Angaben in Ihrem Browser. Senden Sie das Ergebnis ab, legen wir einen Vorgang an; registrieren Sie sich später mit derselben E-Mail, sehen Sie ihn samt Status im Portal.",
  },
  {
    q: "Warum ist die Netzentfernung so wichtig?",
    a: `Jeder Kilometer Mittelspannungskabel kostet grob ${fmt(FREIFLAECHE.kabelProMeter)} Tsd. €. Bei einem kleinen Park fällt das je Kilowatt stark ins Gewicht, bei einem großen kaum. Deshalb rechnet der Check die Netzkosten je kWp – und noch wichtiger ist, ob das Netz überhaupt Kapazität frei hat.`,
  },
  {
    q: "Meine Fläche ist rot – lohnt sich eine Anfrage trotzdem?",
    a: "Oft ja. Die Heuristik kennt Ihre Fläche nicht im Detail. Mit Nachbarflächen, als Agri-PV oder mit einem anderen Netzanschlusspunkt kann ein Projekt trotzdem möglich sein. Wenn nicht, sagen wir es Ihnen offen.",
  },
  {
    q: "Was kostet mich die Prüfung?",
    a: `Nichts. ${PROVISION.flaeche.text[0].toUpperCase()}${PROVISION.flaeche.text.slice(1)} – vom Flächencheck über das Pachtangebot bis zum Vertrag.`,
  },
];

export default function FlaechencheckPage() {
  return (
    <div>
      <script
        type="application/ld+json"
        dangerouslySetInnerHTML={{
          __html: JSON.stringify({
            "@context": "https://schema.org",
            "@type": "WebApplication",
            name: "ÖkoInvest Flächencheck",
            url: abs(PFAD),
            description: BESCHREIBUNG,
            applicationCategory: "BusinessApplication",
            operatingSystem: "Web",
            inLanguage: "de",
            isAccessibleForFree: true,
            offers: { "@type": "Offer", price: "0", priceCurrency: "EUR" },
            publisher: { "@id": `${abs("/")}/#organization` },
          }),
        }}
      />

      <CheckHero />

      <section id="check" aria-label="Flächencheck" className="relative z-10 -mt-20 scroll-mt-24 pb-6 md:-mt-28 md:pb-10">
        <div className="ov-container">
          <FlaechenWizard />
        </div>
      </section>

      <Section tone="white" space="lg">
        <div className="grid gap-10 lg:grid-cols-[1.1fr_0.9fr] lg:gap-16">
          <SoBewertenWir />
          <Reveal className="lg:sticky lg:top-28 lg:self-start">
            <AnnahmenBox
              punkte={[
                ["Ampel", "grün ab 65, gelb ab 40 Punkten"],
                ["Flächenbedarf", `${fmt(FREIFLAECHE.haProMwp, 1)} ha je MWp`],
                ["Mindestgröße Solarpark", `ab ${FREIFLAECHE.mindestHa} ha`],
                ["Kabeltrasse Mittelspannung", `${fmt(FREIFLAECHE.kabelProMeter)} €/m`],
                ["Übergabestation", `${fmt(FREIFLAECHE.netzanschlussFixProMwp)} €/MWp`],
                ["Pacht Freifläche", `${fmt(PACHT.freiflaecheProHa.min)}–${fmt(PACHT.freiflaecheProHa.max)} €/ha·a`],
                ["Pacht Agri-PV", `${fmt(PACHT.agriProHa.min)}–${fmt(PACHT.agriProHa.max)} €/ha·a`],
                ["Indexierung Pacht", `${fmt(PACHT.indexierung * 100, 1)} % p. a.`],
              ]}
              quellen={[
                { name: "PVGIS", url: "https://re.jrc.ec.europa.eu/pvg_tools/de/" },
                { name: "Bundesnetzagentur", url: "https://www.bundesnetzagentur.de/DE/Fachthemen/ElektrizitaetundGas/Ausschreibungen/Solaranlagen1/start.html" },
              ]}
            />
          </Reveal>
        </div>
      </Section>

      <Section tone="sand" space="md">
        <div className="grid gap-10 lg:grid-cols-[0.8fr_1.2fr] lg:gap-20">
          <SectionHeading eyebrow="Häufige Fragen" title="Zum Flächencheck" lead="Ihre Frage ist nicht dabei? Stellen Sie sie im Formular unter dem Ergebnis." />
          <Faq items={FAQ} />
        </div>
      </Section>

      <Querverweise
        items={[
          { href: "/freiflaeche", titel: "Freiflächen-PV", text: "Flächenkriterien, EEG-Kulisse, Genehmigung in DE, AT und CH." },
          { href: "/rechner/pacht", titel: "Pachtrechner", text: "Festpacht, indexiert oder Umsatzbeteiligung über 30 Jahre." },
          { href: "/flaeche-verpachten", titel: "Fläche verpachten", text: "Was im Vertrag steht und wie es bis zur ersten Pacht weitergeht." },
          { href: "/agri-pv", titel: "Agri-PV", text: "Strom und Landwirtschaft auf derselben Fläche." },
        ]}
      />

      <CtaBand
        eyebrow="Persönlich statt Formular"
        title="Lieber gleich mit dem Flächenteam sprechen?"
        text="Schicken Sie uns Ihre Flurstücke – wir prüfen Netz, Kulisse und Restriktionen und melden uns mit einer ehrlichen Einschätzung."
        primary={{ label: "Fläche verpachten", href: "/flaeche-verpachten" }}
        secondary={{ label: "Für Landwirte", href: "/landwirte" }}
      />
    </div>
  );
}
src/app/angebot:
